// The bicubic image resize in front of FoundationStereo's DINOv2 branch,
// `F.interpolate(x, size, mode="bicubic", align_corners=False)`, against PyTorch in
// FP32 (as `Feature` runs it; see the generator). Fixtures generated by tests/fixtures/bicubic/generate.py.
//
// Runs on whichever backend teeny-runtime was built for: CUDA, or RISC-V under qemu
// (`--no-default-features --features qemu`, with
// `TEENYC_QEMU_RISCV64=/usr/bin/qemu-riscv64-static` if only the static qemu exists).

#![cfg(any(feature = "cuda", feature = "qemu"))]

mod common;

use common::stereo_block::check_block;
use serial_test::serial;
use vision_rs::models::stereo::feature::dinov2::resize_input;

fn check(name: &str, input: [usize; 2], size: (usize, usize)) -> anyhow::Result<()> {
    let dir = format!("bicubic/{name}");
    check_block(
        &dir,
        &dir,
        &[("x", &[1, 3, input[0], input[1]])],
        |i| vec![("", resize_input::<f32>(&i[0], size))],
        1e-5,
    )?;
    Ok(())
}

/// 30x44 to 37x61.
#[test]
#[serial]
fn bicubic_enlarge_matches_pytorch() -> anyhow::Result<()> {
    check("up", [30, 44], (37, 61))
}

/// 30x44 to 19x27.
#[test]
#[serial]
fn bicubic_shrink_matches_pytorch() -> anyhow::Result<()> {
    check("down", [30, 44], (19, 27))
}

/// 56x80 to 56x84: the branch's 224x320 to 224x336, scaled down.
#[test]
#[serial]
fn bicubic_branch_resize_matches_pytorch() -> anyhow::Result<()> {
    check("branch", [56, 80], (56, 84))
}

/// The sample left image at 224x320 resized to 224x336, as `Feature.forward` does
/// before the ViT. Tolerance absolute 5e-5: source columns reach ~320, where an f32
/// coordinate resolves only ~1e-5 px (so fma or not in `scale * (o + 0.5) - 0.5`
/// matters), and the normalised image changes by up to ~2 per pixel. Fixtures from tests/fixtures/dinov2/gen_real.py (`dinov2_real/`
/// under `FS_REAL_FIXTURES`); run with `--ignored`.
#[test]
#[serial]
#[ignore = "needs FS_REAL_FIXTURES (real-checkpoint fixtures, not committed)"]
fn bicubic_resize_matches_real_image() -> anyhow::Result<()> {
    let root = std::env::var("FS_REAL_FIXTURES")
        .expect("set FS_REAL_FIXTURES to the real-checkpoint fixture directory");
    let dir = format!("{root}/dinov2_real");
    check_block(
        "bicubic_real",
        &dir,
        &[("image", &[1, 3, 224, 320])],
        |i| vec![("x", resize_input::<f32>(&i[0], (224, 336)))],
        5e-5,
    )?;
    Ok(())
}
